#!/usr/bin/env node
// Writes src/environments/primeui-license.generated.ts from the PRIMEUI_LICENSE env var.
// The generated file is gitignored; the key must never be committed, logged or echoed.
//
//   node scripts/generate-primeui-license.mjs            lenient: empty key -> warning, empty licence (dev, tests)
//   node scripts/generate-primeui-license.mjs --require  strict: empty key -> exit 1 (production build)
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
export const DEFAULT_OUT_FILE = resolve(here, '../src/environments/primeui-license.generated.ts');

/**
 * @param {{env?: Record<string, string | undefined>, outFile?: string, require?: boolean,
 *          log?: (m: string) => void, warn?: (m: string) => void, error?: (m: string) => void}} [opts]
 * @returns {number} process exit code
 */
export function generate({
  env = process.env,
  outFile = DEFAULT_OUT_FILE,
  require = false,
  log = console.log,
  warn = console.warn,
  error = console.error,
} = {}) {
  const key = (env['PRIMEUI_LICENSE'] ?? '').trim();

  if (!key && require) {
    error(
      'PRIMEUI_LICENSE is empty or not set. A production build without a PrimeUI licence key ' +
        'would ship the "Invalid PrimeUI License" banner. Set the PRIMEUI_LICENSE variable ' +
        '(Gitea secret in CI, `export PRIMEUI_LICENSE="$(pbpaste)"` locally).',
    );
    return 1;
  }

  if (!key) {
    warn(
      'WARNING: PRIMEUI_LICENSE is not set: PrimeNG will show its "Invalid PrimeUI License" banner. ' +
        'Fine for quick dev, set it to test with the real licence.',
    );
  }

  const content =
    '// GENERATED by scripts/generate-primeui-license.mjs. Do not edit, do not commit (gitignored).\n' +
    `export const primeuiLicense: string = ${JSON.stringify(key)};\n`;
  mkdirSync(dirname(outFile), { recursive: true });
  writeFileSync(outFile, content, { mode: 0o600 });
  log(`primeui-license: ${key ? 'licence key written to the generated file' : 'empty licence written'}.`);
  return 0;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exitCode = generate({ require: process.argv.includes('--require') });
}
